import { Checkbox as ArkCheckbox } from "@ark-ui/react/checkbox";
import { Check, Minus } from "lucide-react";

import { cn } from "@/lib/utils";

import type { ComponentProps, ReactNode } from "react";

const CheckboxProvider = ArkCheckbox.RootProvider;
const CheckboxGroup = ArkCheckbox.Group;
const CheckboxContext = ArkCheckbox.Context;

const CheckboxRoot = ({
  className,
  ...rest
}: ComponentProps<typeof ArkCheckbox.Root>) => (
  <ArkCheckbox.Root className={cn("flex items-center", className)} {...rest} />
);

const CheckboxLabel = ({
  className,
  ...rest
}: ComponentProps<typeof ArkCheckbox.Label>) => (
  <ArkCheckbox.Label
    className={cn(
      "ml-2 font-medium text-sm leading-snug peer-disabled:cursor-not-allowed peer-disabled:opacity-70",
      className,
    )}
    {...rest}
  />
);

const CheckboxControl = ({
  className,
  ...rest
}: ComponentProps<typeof ArkCheckbox.Control>) => (
  <ArkCheckbox.Control
    className={cn(
      "flex size-5 shrink-0 items-center justify-center rounded-sm border border-primary shadow transition-normal",
      "disabled:cursor-not-allowed peer-disabled:opacity-50",
      "data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground",
      "ring-offset-background peer-focus-visible:ring-2 peer-focus-visible:ring-primary peer-focus-visible:ring-offset-2",
      className,
    )}
    {...rest}
  />
);

const CheckboxIndicator = ({
  className,
  ...rest
}: ComponentProps<typeof ArkCheckbox.Indicator>) => (
  <ArkCheckbox.Indicator className={cn("peer", className)} {...rest} />
);

const CheckboxHiddenInput = ({
  className,
  ...rest
}: ComponentProps<typeof ArkCheckbox.HiddenInput>) => (
  <ArkCheckbox.HiddenInput
    className={cn("peer sr-only", className)}
    {...rest}
  />
);

interface CheckboxProps extends ComponentProps<typeof CheckboxRoot> {
  /** Label beside the box; long labels wrap */
  label?: ReactNode;
}

/**
 * Checkbox with its control, check indicator, hidden input, and optional
 * label. `checked="indeterminate"` shows a dash (e.g. a select-all header). Takes the root's props (`checked`, `onCheckedChange`, `name`,
 * `disabled`, ...). Compose `CheckboxRoot` and its parts for anything else.
 */
const Checkbox = ({ label, ...rest }: CheckboxProps) => (
  <CheckboxRoot {...rest}>
    <CheckboxHiddenInput />
    <CheckboxControl>
      <CheckboxIndicator>
        <Check className="size-3.5" />
      </CheckboxIndicator>
      <CheckboxIndicator indeterminate>
        <Minus className="size-3.5" />
      </CheckboxIndicator>
    </CheckboxControl>
    {label && <CheckboxLabel>{label}</CheckboxLabel>}
  </CheckboxRoot>
);

export {
  Checkbox,
  CheckboxContext,
  CheckboxControl,
  CheckboxGroup,
  CheckboxHiddenInput,
  CheckboxIndicator,
  CheckboxLabel,
  type CheckboxProps,
  CheckboxProvider,
  CheckboxRoot,
};

import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";

import type { ClassValue } from "clsx";

export const cn = (...inputs: ClassValue[]) => {
  return twMerge(clsx(inputs));
};
